const searchPersons = `-- name: SearchPersons :many
SELECT id, code, display_name, title, given, given2, surname, surname_prefix, surname2,
  generation, credentials, preferred, birthdate, date_of_death, sex, country_of_birth_id,
  attributes, status, deactivated_at, purge_after, created_at, updated_at
FROM oikumenea.person_persons
WHERE deleted_at IS NULL AND ($1 = '' OR id::text > $1)
  AND id IN (
    SELECT ps.id FROM oikumenea.person_persons ps
      WHERE ps.deleted_at IS NULL AND ps.search_text ILIKE '%' || $2 || '%'
    UNION
    SELECT v.person_id FROM oikumenea.person_name_variants v
      WHERE v.search_text ILIKE '%' || $2 || '%')
ORDER BY id
LIMIT $3
`

type SearchPersonsParams struct {
	After interface{}
	Query pgtype.Text
	Lim   int32
}

type SearchPersonsRow struct {
	ID               string
	Code             pgtype.Text
	DisplayName      string
	Title            pgtype.Text
	Given            pgtype.Text
	Given2           pgtype.Text
	Surname          pgtype.Text
	SurnamePrefix    pgtype.Text
	Surname2         pgtype.Text
	Generation       pgtype.Text
	Credentials      pgtype.Text
	Preferred        pgtype.Text
	Birthdate        pgtype.Date
	DateOfDeath      pgtype.Date
	Sex              string
	CountryOfBirthID pgtype.Text
	Attributes       []byte
	Status           string
	DeactivatedAt    pgtype.Timestamptz
	PurgeAfter       pgtype.Timestamptz
	CreatedAt        pgtype.Timestamptz
	UpdatedAt        pgtype.Timestamptz
}

// Trigram directory search (review R-06). @query is a non-empty case-insensitive substring; a person
// matches on its own search haystack (display name / code / given / surname) OR any name variant
// (transliteration / alias) — so a native-script or aka form is findable, not just the Latin display
// name. The two match branches are a UNION of id sets so EACH stays a GIN trigram bitmap scan (an
// `A OR EXISTS(subquery)` predicate is NOT indexable and would seq-scan the whole directory); the
// outer keyset then paginates by RID. Sub-3-char queries fall back to a scan (pg_trgm needs a full
// trigram) — acceptable for the rare short-prefix case. Lean column list (review R-17): a per-keystroke
// typeahead path must not hydrate search_text/deleted_at — same lean projection as ListPersons.
func (q *Queries) SearchPersons(ctx context.Context, arg SearchPersonsParams) ([]SearchPersonsRow, error) {
	rows, err := q.db.Query(ctx, searchPersons, arg.After, arg.Query, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchPersonsRow
	for rows.Next() {
		var i SearchPersonsRow
		if err := rows.Scan(
			&i.ID,
			&i.Code,
			&i.DisplayName,
			&i.Title,
			&i.Given,
			&i.Given2,
			&i.Surname,
			&i.SurnamePrefix,
			&i.Surname2,
			&i.Generation,
			&i.Credentials,
			&i.Preferred,
			&i.Birthdate,
			&i.DateOfDeath,
			&i.Sex,
			&i.CountryOfBirthID,
			&i.Attributes,
			&i.Status,
			&i.DeactivatedAt,
			&i.PurgeAfter,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

